<?php
declare(strict_types=1);
namespace app\common\service\app\aigc_copywriting;
use think\facade\Db;
final class CopywritingPageService {
 public static function detail(int $tenantId,int $id=0,string $code=''):array {$row=$id?CopywritingStore::owned('page',$tenantId,$id):CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'page_code'=>$code])->find();if(!$row)throw new \InvalidArgumentException('页面不存在');$row['document']=CopywritingStore::decode($row['draft_json']);unset($row['draft_json']);return $row;}
 public static function saveDraft(int $tenantId,int $actorId,int $id,int $expected,array $document):array {$d=CopywritingDocument::normalize($document);$errors=CopywritingDocument::validate($d);if($errors)throw new \InvalidArgumentException($errors[0]['message'].'：'.$errors[0]['path']);$count=CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'id'=>$id,'draft_revision'=>$expected])->update(['draft_json'=>CopywritingStore::json($d),'draft_revision'=>$expected+1,'update_time'=>time()]);if(!$count)throw new \RuntimeException('页面已被修改，请刷新后重新编辑',409);CopywritingStore::audit($tenantId,$actorId,'save_draft','page',$id);return self::detail($tenantId,$id);}
 public static function publish(int $tenantId,int $actorId,int $id,int $expected,array $targets):array {return Db::transaction(function()use($tenantId,$actorId,$id,$expected,$targets){$row=CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'id'=>$id])->lock(true)->find();if(!$row||$row['draft_revision']!=$expected)throw new \RuntimeException('草稿版本已变化',409);$d=CopywritingStore::decode($row['draft_json']);CopywritingDocument::assertValid($d,$targets);$names=[];self::walk($d['page']['nodes'],function($n)use(&$names){$names[]=$n['name'];});if($row['kind']==='tool')foreach(['cw-model','cw-submit','cw-result']as $required)if(!in_array($required,$names,true))throw new \InvalidArgumentException('页面缺少模型选择、生成按钮或结果组件');$v=(int)CopywritingStore::table('version')->where('page_id',$id)->max('version_no')+1;$version=CopywritingStore::insert('version',['tenant_id'=>$tenantId,'page_id'=>$id,'version_no'=>$v,'document_json'=>$row['draft_json'],'schema_hash'=>hash('sha256',$row['draft_json']),'publisher_id'=>$actorId,'publish_targets'=>implode(',',array_intersect($targets,['pc','h5','mp-weixin']))]);CopywritingStore::table('page')->where('id',$id)->update(['published_version_id'=>$version,'update_time'=>time()]);CopywritingStore::audit($tenantId,$actorId,'publish','page',$id);return ['version_id'=>$version,'version_no'=>$v];});}
 public static function walk(array $nodes,callable $fn):void{foreach($nodes as $n){$fn($n);self::walk($n['children']??[],$fn);}}
 public static function versions(int $tenantId,int $pageId):array {CopywritingStore::owned('page',$tenantId,$pageId);return CopywritingStore::table('version')->where(['tenant_id'=>$tenantId,'page_id'=>$pageId])->field('id,version_no,schema_hash,publish_targets,create_time')->order('id','desc')->select()->toArray();}
 public static function rollback(int $tenantId,int $actorId,int $pageId,int $versionId,int $expected):array {$v=CopywritingStore::owned('version',$tenantId,$versionId);if((int)$v['page_id']!==$pageId)throw new \InvalidArgumentException('版本不属于该页面');self::saveDraft($tenantId,$actorId,$pageId,$expected,CopywritingStore::decode($v['document_json']));return self::publish($tenantId,$actorId,$pageId,$expected+1,explode(',',$v['publish_targets']));}
}
